% 📏 Absolute edge-weight, degree and incident-strength extrema for network encodings.
\cs_new_protected:Npn \semio_viz_net_extremes: {
  \semio_viz_network_fp_ensure:nn { strength } { \l_semio_viz_network_n_int }
  \int_step_inline:nn { \l_semio_viz_network_n_int }
    { \semio_viz_network_fset:nnn { strength } {##1} { 0 } }
  \fp_set:Nn \l_semio_viz_net_wmin_fp { inf }
  \fp_zero:N \l_semio_viz_net_wmax_fp
  \int_step_inline:nn { \l_semio_viz_network_m_int } {
    \fp_set:Nn \l_semio_viz_net_a_fp { abs( \semio_viz_network_f:nn { ew } {##1} ) }
    \fp_set:Nn \l_semio_viz_net_wmin_fp { min( \l_semio_viz_net_wmin_fp , \l_semio_viz_net_a_fp ) }
    \fp_set:Nn \l_semio_viz_net_wmax_fp { max( \l_semio_viz_net_wmax_fp , \l_semio_viz_net_a_fp ) }
    \semio_viz_network_fadd:nnn { strength } { \semio_viz_network_n:nn { es } {##1} } { \l_semio_viz_net_a_fp }
    \semio_viz_network_fadd:nnn { strength } { \semio_viz_network_n:nn { et } {##1} } { \l_semio_viz_net_a_fp }
  }
  \fp_compare:nNnT \l_semio_viz_net_wmin_fp = { inf } { \fp_zero:N \l_semio_viz_net_wmin_fp }
  \fp_set:Nn \l_semio_viz_net_dmax_fp { 1 }
  \fp_zero:N \l_semio_viz_net_strength_max_fp
  \int_step_inline:nn { \l_semio_viz_network_n_int } {
    \fp_set:Nn \l_semio_viz_net_dmax_fp
      { max( \l_semio_viz_net_dmax_fp , \semio_viz_network_n:nn { deg } {##1} ) }
    \fp_set:Nn \l_semio_viz_net_strength_max_fp
      { max( \l_semio_viz_net_strength_max_fp , \semio_viz_network_f:nn { strength } {##1} ) }
  }
  \fp_compare:nNnT \l_semio_viz_net_strength_max_fp = { 0 }
    { \fp_set:Nn \l_semio_viz_net_strength_max_fp { 1 } }
}
\fp_new:N \l_semio_viz_net_dmax_fp
\fp_new:N \l_semio_viz_net_strength_max_fp

% 🌓 Draws the full matrix or shares its ordered canvas with the node-link view.
\cs_new_protected:Npn \semio_viz_mat_draw: {
  \bool_if:NTF \l_semio_viz_mat_split_bool
    {
      \fp_set_eq:NN \l_semio_viz_mat_right_fp \l_semio_viz_net_xhi_fp
      \fp_set:Nn \l_semio_viz_net_xhi_fp
        { \l_semio_viz_net_xlo_fp + 0.52 * ( \l_semio_viz_mat_right_fp - \l_semio_viz_net_xlo_fp ) }
      \semio_viz_mat_grid_draw:
      \fp_set:Nn \l_semio_viz_net_xlo_fp { \l_semio_viz_net_xhi_fp + 2 }
      \fp_set_eq:NN \l_semio_viz_net_xhi_fp \l_semio_viz_mat_right_fp
      \semio_viz_mat_line_draw:
    }
    { \semio_viz_mat_grid_draw: }
}

