% 📝 Draws the diagram caption and explicitly localized lane heading above their frame.
\cs_new_protected:Npn \semio_viz_dg_titles: {
  \tl_if_empty:NF \l_semio_viz_dg_title_tl {
    \node [ font=\c_semio_viz_theme_font_title_tl , text=semio-chrome-text-normal , anchor=south , inner~sep=0mm ]
      at ( \fp_eval:n { \l_semio_viz_dg_w_fp / 2 } , \fp_eval:n { \l_semio_viz_dg_h_fp + 5 } )
      { \tl_use:N \l_semio_viz_dg_title_tl } ;
  }
  \str_if_eq:VnF \l_semio_viz_dg_lanemode_tl { none } {
    \tl_if_empty:NF \l_semio_viz_dg_lanetitle_tl {
      \seq_set_split:NnV \l_semio_viz_dg_title_parts_seq { // } \l_semio_viz_dg_lanetitle_tl
      \int_case:nnF { \seq_count:N \l_semio_viz_dg_title_parts_seq } {
        { 1 } { \tl_set_eq:NN \l_semio_viz_dg_ta_tl \l_semio_viz_dg_lanetitle_tl }
        { 2 } {
          \str_case:VnF \l_semio_language_tl {
            { en } { \tl_set:Nx \l_semio_viz_dg_ta_tl { \seq_item:Nn \l_semio_viz_dg_title_parts_seq { 1 } } }
            { de } { \tl_set:Nx \l_semio_viz_dg_ta_tl { \seq_item:Nn \l_semio_viz_dg_title_parts_seq { 2 } } }
          } { \msg_error:nnx { semio-viz } { diagram-language } { \l_semio_language_tl } }
        }
      } { \msg_error:nn { semio-viz } { diagram-lane-title } }
      \node [ font=\c_semio_viz_theme_font_chip_tl , text=semio-chrome-text-normal , anchor=south~west , inner~sep=0mm ]
        at ( 0 , \fp_eval:n { \l_semio_viz_dg_h_fp + 0.8 } ) { \tl_use:N \l_semio_viz_dg_ta_tl } ;
    }
  }
}

